cd /tmp; cat > /tmp/promq.py <<'EOF'
import json, sys, urllib.parse, urllib.request
base = "http://prometheus-kube-prometheus-prometheus.prometheus.svc:9090/api/v1/query"
for q in sys.argv[1:]:
    print("###", q)
    try:
        url = base + "?" + urllib.parse.urlencode({"query": q})
        r = json.load(urllib.request.urlopen(url, timeout=15))["data"]["result"]
        for x in r:
            print(" ", {k: v for k, v in x["metric"].items() if k in ("service_name", "status_code", "namespace")}, x["value"][1][:8])
        if not r: print("  (no data)")
    except Exception as e:
        print("  ERR", e)
EOF
